// Adventure controller: one session clock and one animation loop, cleaned up on exit.
const originalRender=render,originalPlay=renderPlay;
let session=null,trial=null,tickId=null,frameId=null,rewardId=null,nextTrial=0,menuChoice=0;
function stopLoops(){clearInterval(tickId);cancelAnimationFrame(frameId);clearTimeout(rewardId);tickId=null;frameId=null;rewardId=null}
function removeOverlay(){document.getElementById('challengeOverlay')?.remove();document.querySelector('main').inert=false;document.getElementById('hud')?.removeAttribute('inert')}
function showOverlay(html){removeOverlay();const overlay=document.createElement('div');overlay.id='challengeOverlay';overlay.className='modal-shade';overlay.innerHTML='<section class="challenge" role="dialog" aria-modal="true" aria-label="Prueba del sabio" tabindex="-1">'+html+'</section>';document.body.append(overlay);document.querySelector('main').inert=true;document.getElementById('hud')?.setAttribute('inert','');overlay.querySelector('.challenge').focus()}
function menu(){stopLoops();trial=null;session=null;removeOverlay();document.getElementById('hud')?.remove();document.getElementById('menu')?.remove();document.body.classList.add('menu-mode');const m=document.createElement('section');m.id='menu';m.className='menu-wrap';m.innerHTML='<div class="menu-paper"><div class="eyebrow">El archivo del sabio</div><div class="menu-rune">✦</div><h1>Rescate del<br><em>Código Perdido</em></h1><p>Un antiguo pergamino. Un código roto.<br>Tu ingenio y tus reflejos romperán el sello.</p><div class="menu-select"><button id="choose0">I · El número secreto</button><button id="choose1">II · El duelo del sabio</button></div><button class="primary" id="startAdventure">Desplegar el pergamino · Iniciar</button><div class="menu-help">♥ 3 corazones &nbsp; ◷ 5 minutos<br>Ordena las piezas y comprueba el código. Si falla, el sabio pondrá a prueba tus reflejos. El reloj principal se pausa durante las pruebas.<br><br><b>Teclas:</b> completa 8 símbolos en 10 segundos: pista + 1 corazón.<br><b>Aguja:</b> 5 aciertos: pista + 2 corazones; 3–4: +1 corazón; 0–2: −1 corazón.<br>Las pistas aparecen durante 7 segundos. Máximo: 3 corazones.</div></div>';document.querySelector('footer').before(m);const select=i=>{menuChoice=i;[0,1].forEach(j=>$('choose'+j).classList.toggle('active',i===j))};[0,1].forEach(i=>$('choose'+i).onclick=()=>select(i));select(menuChoice);$('startAdventure').onclick=()=>startAdventure(menuChoice)}
function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}if(a.every((v,i)=>v===i))a.reverse();return a}
function startAdventure(chapter){stopLoops();trial=null;removeOverlay();document.getElementById('hud')?.remove();document.getElementById('menu')?.remove();document.body.classList.remove('menu-mode');current=chapter;states[current]={order:shuffle(chapters[current].pieces.map((_,i)=>i)),solved:false,selected:null,hint:0};session={hearts:3,remaining:300000,last:performance.now(),phase:'puzzle'};nextTrial=0;const hud=document.createElement('div');hud.id='hud';hud.className='hud';hud.innerHTML='<span class="hearts" id="hearts" aria-label="3 corazones">♥♥♥</span><span class="clock" id="clock">05:00</span><button id="backMenu">Menú</button>';document.querySelector('header').after(hud);$('backMenu').onclick=menu;document.querySelector('.tabs').hidden=true;$('hintText').textContent='Una restauración incorrecta activa una prueba de reflejos. Gánala para conseguir pistas y recuperar corazones.';render();tickId=setInterval(()=>{if(!session)return;const now=performance.now();if(session.phase==='puzzle')session.remaining=Math.max(0,session.remaining-(now-session.last));session.last=now;updateHud();if(session.phase==='puzzle'&&session.remaining<=0)endAdventure('El tiempo se agotó','El pergamino vuelve a sellarse. Inténtalo de nuevo.');},100)}
function updateHud(){if(!session||!$('hearts'))return;$('hearts').textContent='♥'.repeat(session.hearts)+'♡'.repeat(3-session.hearts);$('hearts').setAttribute('aria-label',session.hearts+' corazones');const seconds=Math.ceil(session.remaining/1000);$('clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('clock').classList.toggle('urgent',seconds<=30)}
render=function(){originalRender();if(!session||session.phase!=='puzzle'||states[current].solved)return;$('hint').remove();$('check').onclick=()=>{if(states[current].order.every((v,i)=>v===i)){session.phase='won';clearInterval(tickId);states[current].solved=true;$('panel').innerHTML='<div class="arena break"><span class="rock">🪨</span><span class="rune">✦</span><span class="rock">🪨</span></div><h2>¡El sello se ha roto!</h2><p>Restauraste el código con '+session.hearts+' corazones. La obra del sabio vuelve a vivir.</p>';rewardId=setTimeout(()=>{if(session?.phase==='won')renderPlay()},1100)}else prepareTrial()}}
renderPlay=function(){if(session){session.phase='won';clearInterval(tickId)}originalPlay();$('restore').textContent='Reiniciar aventura';$('restore').onclick=()=>startAdventure(current)}
function prepareTrial(){if(!session||session.phase!=='puzzle')return;session.phase='trial';session.last=performance.now();trial={kind:nextTrial++%2?'dial':'keys'};showOverlay('<div class="eyebrow">El código todavía no encaja</div><h2>'+ (trial.kind==='keys'?'Las runas veloces':'La aguja del destino')+'</h2><p>'+ (trial.kind==='keys'?'Pulsa la tecla que aparece. Completa 8 antes de que se vacíe la barra. Una tecla incorrecta resta un segundo.':'Pulsa ESPACIO cuando la punta de la aguja esté en el cuadrado dorado. Son 5 círculos, cada uno en un lugar distinto. Tienes 5 segundos por círculo.')+'</p><p>El reloj del pergamino está pausado.</p><button class="primary" id="beginTrial">Estoy listo · Comenzar</button>');$('beginTrial').onclick=()=>trial.kind==='keys'?startKeys():startDial()}
function startKeys(){trial={kind:'keys',active:true,done:0,key:randomKey(),ends:performance.now()+8500};showOverlay('<div class="eyebrow">Prueba de reflejos · runas</div><h2>Invoca las 8 runas</h2><button class="key-tile" id="keyTile" aria-label="Pulsar la runa indicada"></button><p id="keyProgress">0 / 8</p><div class="life-track"><div class="life-fill" id="trialBar"></div></div><p>Pulsa la letra indicada o toca la runa.</p>');$('keyTile').textContent=trial.key;$('keyTile').onclick=()=>keyAttempt(trial?.key);frameId=requestAnimationFrame(trialFrame)}
function randomKey(){return 'ASDFJKL'[Math.floor(Math.random()*7)]}
function keyAttempt(key){if(!trial?.active||trial.kind!=='keys')return;if(performance.now()>=trial.ends){finishTrial(false,0);return}if(key!==trial.key){trial.ends-=1000;$('keyTile').classList.remove('error-flash');void $('keyTile').offsetWidth;$('keyTile').classList.add('error-flash');return}trial.done++;if(trial.done===8){finishTrial(true,1);return}let next=randomKey();if(next===trial.key)next='ASDFJKL'[('ASDFJKL'.indexOf(next)+1)%7];trial.key=next;$('keyTile').textContent=next;$('keyProgress').textContent=trial.done+' / 8'}
function startDial(){trial={kind:'dial',active:true,round:0,hits:0,results:[],started:0,angle:0,target:0};showOverlay('<div class="eyebrow">Prueba de reflejos · precisión</div><h2>La aguja del destino</h2><div class="rounds" id="rounds"></div><div class="trial-field" id="trialField"><div class="dial" id="dial"><div class="target-square" id="targetSquare"></div><div class="needle" id="needle"></div></div></div><div class="life-track"><div class="life-fill" id="trialBar"></div></div><button class="primary" id="stopNeedle">ESPACIO · Detener aguja</button><p id="dialProgress"></p>');$('stopNeedle').onclick=dialAttempt;newDial();frameId=requestAnimationFrame(trialFrame)}
function newDial(){trial.started=performance.now();trial.ends=trial.started+4000;trial.target=Math.random()*360;trial.offset=Math.random()*360;trial.angle=trial.offset;const field=$('trialField'),dial=$('dial');dial.style.left=Math.floor(Math.random()*Math.max(1,field.clientWidth-160))+5+'px';dial.style.top=Math.floor(Math.random()*Math.max(1,field.clientHeight-160))+5+'px';$('targetSquare').style.setProperty('--target',trial.target+'deg');$('needle').style.transform='rotate('+trial.angle+'deg)';$('rounds').textContent=trial.results.map(v=>v?'✦':'×').join(' ')+' '+Array(5-trial.results.length).fill('○').join(' ');$('dialProgress').textContent='Círculo '+(trial.round+1)+' / 5 · Aciertos: '+trial.hits}
function angularDistance(a,b){return Math.abs(((a-b+540)%360)-180)}
function dialAttempt(){if(!trial?.active||trial.kind!=='dial')return;const now=performance.now();trial.angle=((now-trial.started)*.22+trial.offset)%360;const hit=now<trial.ends&&angularDistance(trial.angle,trial.target)<=13;trial.results.push(hit);if(hit)trial.hits++;trial.round++;if(trial.round>=5){const hits=trial.hits;finishTrial(hits===5,hits===5?2:hits>=3?1:0,hits);return}newDial()}
function trialFrame(){if(!trial?.active)return;const now=performance.now();if(trial.kind==='keys'){if(now>=trial.ends){finishTrial(false,0);return}$('trialBar').style.transform='scaleX('+Math.max(0,(trial.ends-now)/8500)+')'}else{if(now>=trial.ends){dialAttempt();if(!trial?.active)return}trial.angle=((now-trial.started)*.22+trial.offset)%360;$('needle').style.transform='rotate('+trial.angle+'deg)';$('trialBar').style.transform='scaleX('+Math.max(0,(trial.ends-now)/4000)+')'}frameId=requestAnimationFrame(trialFrame)}
function essentialHint(){const first=states[current].order.findIndex((v,i)=>v!==i);return 'El fragmento '+(first+1)+' debe contener:\n'+chapters[current].pieces[first]}
function finishTrial(pista,heal,hits){cancelAnimationFrame(frameId);const kind=trial.kind;trial=null;if(heal)session.hearts=Math.min(3,session.hearts+heal);else session.hearts=Math.max(0,session.hearts-1);updateHud();if(session.hearts===0){endAdventure('Sin corazones','El sabio guarda el pergamino hasta tu próximo intento.');return}const title=pista?'¡Prueba superada!':heal?'Buen pulso':'El sello resiste';const message=heal?'Recuperas hasta '+heal+' corazón'+(heal>1?'es':'')+'.':'Pierdes 1 corazón.';showOverlay('<h2>'+title+'</h2><div class="reward">'+message+'</div>'+(hits!==undefined?'<p>'+hits+' aciertos de 5</p>':'')+(pista?'<div class="hint-paper" id="earnedHint"></div><p>Memoriza la pista. Desaparecerá en 7 segundos.</p>':'<p>Respira, revisa el código y vuelve a intentarlo.</p><button id="resumeAdventure" class="primary">Volver al pergamino</button>'));if(pista){$('earnedHint').textContent=essentialHint();$('earnedHint').style.whiteSpace='pre-line';rewardId=setTimeout(resumeAdventure,7000)}else $('resumeAdventure').onclick=resumeAdventure}
function resumeAdventure(){if(!session)return;removeOverlay();session.phase='puzzle';session.last=performance.now();render();$('check')?.focus()}
function endAdventure(title,message){stopLoops();trial=null;session.phase='lost';showOverlay('<div class="eyebrow">Fin de la aventura</div><h2>'+title+'</h2><p>'+message+'</p><button class="primary" id="retryAdventure">Volver a intentarlo</button><button id="endMenu">Menú del pergamino</button>');$('retryAdventure').onclick=()=>startAdventure(current);$('endMenu').onclick=menu}
document.addEventListener('keydown',event=>{if(!trial?.active||event.repeat||event.ctrlKey||event.altKey||event.metaKey)return;if(trial.kind==='keys'&&/^[a-z]$/i.test(event.key)){event.preventDefault();keyAttempt(event.key.toUpperCase())}else if(trial.kind==='dial'&&event.code==='Space'){event.preventDefault();dialAttempt()}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&session?.phase==='puzzle'){const now=performance.now();session.remaining=Math.max(0,session.remaining-(now-session.last));session.last=now;updateHud();if(!session.remaining)endAdventure('El tiempo se agotó','El pergamino vuelve a sellarse.')}});
menu();



